Solution A: function generateAndSolveMaze(canvasId, width, height) {
  const canvas = document.getElementById(canvasId);
  const ctx = canvas.getContext("2d");
  canvas.setAttribute("width", width);
  canvas.setAttribute("height", height);

  const visited = [];
  const openList = [];

  function generateMaze(x, y, size) {
    if (size < 1) return;
    visited.push({ x, y });

    while (true) {
      let hasNeighbors = false;
      if (x > 1 && !visited.some(node => node.x === x - 1 && node.y === y)) {
        hasNeighbors = true;
        break;
      }
      if (x < width - 2 && !visited.some(node => node.x === x + 1 && node.y === y)) {
        hasNeighbors = true;
        break;
      }
      if (y > 1 && !visited.some(node => node.x === x && node.y === y - 1)) {
        hasNeighbors = true;
        break;
      }
      if (y < height - 2 && !visited.some(node => node.x === x && node.y === y + 1)) {
        hasNeighbors = true;
        break;
      }
      if (hasNeighbors) break;
    }

    let nextX, nextY;
    do {
      if (Math.random() < 0.5) {
        nextX = x - 1;
        nextY = y;
      } else {
        nextX = x + 1;
        nextY = y;
      }
    } while (visited.some(node => node.x === nextX && node.y === nextY))
    generateMaze(nextX, nextY, size - 2);
    do {
      if (Math.random() < 0.5) {
        nextX = x;
        nextY = y - 1;
      } else {
        nextX = x;
        nextY = y + 1;
      }
    } while (visited.some(node => node.x === nextX && node.y === nextY))
    generateMaze(nextX, nextY, size - 2);

    draw(x, y, "#ff0000");
  }

  function draw(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * 10, y * 10, 10, 10);
  }

  function solveMaze(startX, startY) {
    const frontier = [{ x: startX, y: startY }];
    let last = null;

    while (frontier.length > 0) {
      last = frontier.shift();
      if (last.x === width - 1 && last.y === height - 1) {
        return last;
      }
      draw(last.x, last.y, "#0000ff");
      if (last.x > 0 && !openList.some(node => node.x === last.x - 1 && node.y === last.y)) {
        openList.push({ x: last.x - 1, y: last.y });
      }
      if (last.x < width - 1 && !openList.some(node => node.x === last.x + 1 && node.y === last.y)) {
        openList.push({ x: last.x + 1, y: last.y });
      }
      if (last.y > 0 && !openList.some(node => node.x === last.x && node.y === last.y - 1)) {
        openList.push({ x: last.x, y: last.y - 1 });
      }
      if (last.y < height - 1 && !openList.some(node => node.x === last.x && node.y === last.y + 1)) {
        openList.push({ x: last.x, y: last.y + 1 });
      }
    }
    return null;
  }

  draw.bind(ctx)(0, 0, "#ffffff");
  generateMaze(width / 2, height / 2, Math.min(width, height));
  const end = solveMaze(0, 0);

  let current = end;
  while (current.x !== 0 || current.y !== 0) {
    openList.push(current);
    current = openList
      .filter(node => Math.abs(node.x - current.x) === 1 || Math.abs(node.y - current.y) === 1)
      .reduce((best, node) => best heuristic(node) < node.heuristic(node) ? best : node, { x: 0, y: 0 })
  }
  while (openList.length > 0) {
    current = openList.shift();
    draw(current.x, current.y, "#00ff00");
  }
}

Solution B: ```javascript
function generateAndSolveMaze(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) {
        console.error("Canvas not found");
        return;
    }
    const ctx = canvas.getContext('2d');
    const width = 500;
    const height = 500;
    const cellSize = 10;
    const cols = width / cellSize;
    const rows = height / cellSize;

    let maze = Array.from({ length: rows }, () => Array(cols).fill(0));
    let openSet = [];
    let closedSet = [];
    let startNode, endNode;

    function drawMaze() {
        for (let y = 0; y < rows; y++) {
            for (let x = 0; x < cols; x++) {
                if (maze[y][x] === 1) {
                    ctx.fillStyle = 'black';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                } else {
                    ctx.fillStyle = 'white';
                    ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
                }
            }
        }
    }

    function recursiveDivision(x1, y1, x2, y2, horizontal) {
        if (horizontal) {
            if (y2 - y1 > 1) {
                const wallY = Math.floor(Math.random() * ((y2 - y1) / 2)) * 2 + y1 + 1;
                for (let x = x1; x <= x2; x++) {
                    maze[wallY][x] = 1;
                }
                recursiveDivision(x1, y1, x2, wallY, false);
                recursiveDivision(x1, wallY + 1, x2, y2, false);
            }
        } else {
            if (x2 - x1 > 1) {
                const wallX = Math.floor(Math.random() * ((x2 - x1) / 2)) * 2 + x1 + 1;
                for (let y = y1; y <= y2; y++) {
                    maze[y][wallX] = 1;
                }
                recursiveDivision(x1, y1, wallX, y2, true);
                recursiveDivision(wallX + 1, y1, x2, y2, true);
            }
        }
    }

    function solveMaze() {
        startNode = { x: 0, y: 0 };
        endNode = { x: cols - 1, y: rows - 1 };
        openSet.push(startNode);

        while (openSet.length > 0) {
            let current = openSet.reduce((prev, curr) => prev.f < curr.f ? prev : curr);
            if (current.x === endNode.x && current.y === endNode.y) {
                let path = [];
                let temp = current;
                while (temp.parent) {
                    path.unshift(temp);
                    temp = temp.parent;
                }
                path.forEach(node => {
                    maze[node.y][node.x] = 2;
                    drawMaze();
                    requestAnimationFrame(() => {
                        maze[node.y][node.x] = 3;
                        drawMaze();
                    });
                });
                break;
            }

            openSet = openSet.filter(node => node !== current);
            closedSet.push(current);

            let neighbors = getNeighbors(current);
            neighbors.forEach(neighbor => {
                if (!closedSet.includes(neighbor)) {
                    neighbor.g = current.g + 1;
                    neighbor.h = Math.abs(neighbor.x - endNode.x) + Math.abs(neighbor.y - endNode.y);
                    neighbor.f = neighbor.g + neighbor.h;
                    neighbor.parent = current;
                    if (!openSet.includes(neighbor)) {
                        openSet.push(neighbor);
                    }
                }
            });

            maze[current.y][current.x] = 4;
            drawMaze();
            requestAnimationFrame(() => {
                maze[current.y][current.x] = 5;
                drawMaze();
            });
        }
    }

    function getNeighbors(node) {
        let neighbors = [];
        let directions = [
            { x: 0, y: -1 },
            { x: 0, y: 1 },
            { x: -1, y: 0 },
            { x: 1, y: 0 }
        ];
        directions.forEach(dir => {
            let newX = node.x + dir.x;
            let newY = node.y + dir.y;
            if (newX >= 0 && newX < cols && newY >= 0 && newY < rows && maze[newY][newX] !== 1) {
                neighbors.push({ x: newX, y: newY });
            }
        });
        return neighbors;
    }

    recursiveDivision(0, 0, cols - 1, rows - 1, true);
    drawMaze();
    requestAnimationFrame(solveMaze);
}
